/**
 * Build the DSH client bundle from the readable panel source and generate the
 * browser copy artifact from the one authoritative i18n catalog.
 *
 * DSH dynamic client bundles are lazy CommonJS factories registered on the
 * page's module loader. The generated files are committed so an installed
 * tarball works without a build step; this script keeps source, bundle, and
 * browser dictionary in sync and is exercised by the package tests.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  CATALOG,
  DEFAULT_LANGUAGE,
  LANGUAGES,
} from '../src/i18n/catalog.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(ROOT, 'src', 'client-panel.js');
const OUTPUT = join(ROOT, 'src', 'client.js');
const CONSOLE_I18N_OUTPUT = join(ROOT, 'src', 'console', 'i18n.js');
const HEADER = '// Generated by scripts/build-client.mjs from src/client-panel.js. Do not edit by hand.\n';
const CONSOLE_I18N_HEADER = '/* Generated by scripts/build-client.mjs from src/i18n/catalog.js. Do not edit by hand. */\n';

/** Marker in src/client-panel.js replaced by the shared catalog at build time. */
export const I18N_MARKER = '/* @amadeus-persona-i18n */ null';

/**
 * @param {Record<string, Record<string, string>>} [catalog] shared dictionary.
 * @returns {string} frozen JavaScript literal.
 */
export function renderCatalogLiteral(catalog = CATALOG) {
  return `Object.freeze(${JSON.stringify(catalog)})`;
}

/**
 * @param {string} source panel factory body.
 * @param {Record<string, Record<string, string>>} [catalog] shared dictionary.
 * @returns {string} lazy-CJS module loader bundle.
 */
export function renderClient(source, catalog = CATALOG) {
  const text = String(source);
  if (!text.includes(I18N_MARKER)) {
    throw new Error(`src/client-panel.js must contain the i18n marker: ${I18N_MARKER}`);
  }
  const filled = text.replace(I18N_MARKER, renderCatalogLiteral(catalog));
  return `${HEADER}window.__ModuleLoader__.load({id:'@amadeus/persona',factory:(require)=>{\n${filled.replace(/\s+$/, '')}\n}});\n`;
}

/**
 * @param {Record<string, Record<string, string>>} [catalog] shared dictionary.
 * @returns {string} browser script that publishes the shared catalog.
 */
export function renderConsoleI18n(catalog = CATALOG) {
  return `${CONSOLE_I18N_HEADER}(function () {
  'use strict';
  window.__AmadeusPersonaI18n = Object.freeze({
    defaultLanguage: ${JSON.stringify(DEFAULT_LANGUAGE)},
    languages: Object.freeze(${JSON.stringify(LANGUAGES)}),
    catalog: ${renderCatalogLiteral(catalog)},
  });
})();
`;
}

/**
 * Generate and write src/client.js and src/console/i18n.js.
 * @returns {Promise<string>} generated client bundle.
 */
export async function buildClient() {
  const source = await readFile(SOURCE, 'utf8');
  const output = renderClient(source);
  const consoleI18n = renderConsoleI18n();
  await writeFile(OUTPUT, output, 'utf8');
  await writeFile(CONSOLE_I18N_OUTPUT, consoleI18n, 'utf8');
  return output;
}

const invokedDirectly = process.argv[1] !== undefined
  && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));

if (invokedDirectly) {
  const output = await buildClient();
  process.stdout.write(`Wrote src/client.js (${Buffer.byteLength(output)} bytes).\n`);
  const consoleI18n = await readFile(CONSOLE_I18N_OUTPUT, 'utf8');
  process.stdout.write(`Wrote src/console/i18n.js (${Buffer.byteLength(consoleI18n)} bytes).\n`);
}
